targets.rawSql:
SELECT month, commits, merged, reverted, reworked, open, abandoned, undecided, rework_share
FROM agents.shipping_rework_monthly
ORDER BY month DESC LIMIT 12;

SELECT month, coalesce(category, 'unknown') AS category, units, unit_share, unknown_share
FROM agents.work_mix_monthly
ORDER BY month DESC, units DESC LIMIT 60;
